BEGIN;
SET TRANSACTION ISOLATION LEVEL READ COMMITTED;
COMMIT;
-- Verification: zero rows means no active installation violates the exact BOM SKU mapping.
SELECT c.id FROM item_components c JOIN inventory_items p ON p.id=c.parent_item_id JOIN inventory_items i ON i.id=c.component_item_id JOIN part_components b ON b.id=c.part_component_id WHERE c.removed_at IS NULL AND (p.part_id<>b.parent_part_id OR i.part_id<>b.child_part_id);
-- Fixture row counts
SELECT (SELECT count(*) FROM parts) AS skus,(SELECT count(*) FROM part_components) AS bom_edges,(SELECT count(*) FROM inventory_items) AS inventory_units,(SELECT count(*) FROM item_components) AS installations;
